#!/usr/bin/env node
// Generates real evidence for a phase: `npm run proof -- 1` -> docs/proof/phase-1/
// - runs every scenario case through the headless CLI, saves inputs + raw JSONL output
// - determinism: runs the same default night twice and compares SHA-256
// - runs `npm test` and saves its output
// Never hand-edit the generated files.
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { cpus, platform, release } from 'node:os';
import { runCase, ROOT } from './scenario-check.js';

const phase = process.argv[2] || '1';
const outDir = join(ROOT, 'docs', 'proof', `phase-${phase}`);
const runsDir = join(outDir, 'runs');
mkdirSync(runsDir, { recursive: true });
const rel = (p) => p.slice(ROOT.length).replace(/\\/g, '/').replace(/^\//, '');
const md = [];
const commit = spawnSync('git', ['rev-parse', '--short', 'HEAD'], { cwd: ROOT, encoding: 'utf8' }).stdout.trim();
md.push(`# Proof — Phase ${phase}`, '', `Generated by \`npm run proof -- ${phase}\` at base commit \`${commit}\` on ${platform()} ${release()}, Node ${process.version}, ${cpus()[0]?.model ?? 'cpu'}.`, '');

// 1. Scenario cases
md.push('## Headless scenarios', '', '| Case | Requirement | Result | Output |', '|---|---|---|---|');
let allPass = true;
const scDir = join(ROOT, 'tests', 'scenarios');
for (const f of readdirSync(scDir).filter((x) => x.endsWith('.json'))) {
  for (const c of JSON.parse(readFileSync(join(scDir, f), 'utf8'))) {
    const t0 = performance.now();
    const r = runCase(c, runsDir);
    const ms = (performance.now() - t0).toFixed(0);
    allPass &&= r.pass;
    const end = r.lines.at(-1);
    md.push(`| \`${c.name}\` | ${c.requirement} | ${r.pass ? 'PASS' : 'FAIL: ' + r.failures.join('; ')} | [jsonl](runs/${c.name}.jsonl) · end=\`${JSON.stringify(end)}\` · ${ms} ms |`);
  }
}

// 2. Determinism
const det = [];
for (const n of ['det-a', 'det-b']) {
  const out = join(runsDir, `${n}.jsonl`);
  spawnSync('node', ['src/headless.js', '--seed', '777', '--night', '1', '--ticks', '18000', '--out', out], { cwd: ROOT });
  det.push(createHash('sha256').update(readFileSync(out)).digest('hex'));
}
const detPass = det[0] === det[1];
allPass &&= detPass;
md.push('', '## Determinism', '', 'Command (run twice): `node src/headless.js --seed 777 --night 1 --ticks 18000 --out runs/det-{a,b}.jsonl`', '', `- det-a sha256: \`${det[0]}\``, `- det-b sha256: \`${det[1]}\``, `- Result: **${detPass ? 'PASS (identical)' : 'FAIL (differ)'}**`);

// 2b. Performance: a full night (21,600 ticks) per night through the CLI, limit 30 s (Contract v1.1)
md.push('', '## Headless performance (full night, 21,600 ticks, limit 30 s)', '', '| Night | Wall time | Result |', '|---|---|---|');
for (const night of [1, 2, 3]) {
  const scen = join(runsDir, `perf-n${night}.scenario.json`);
  // survive the whole night: invulnerable to shades, and no wind (gusts would push a standing player off Night 3 -> 3 falls)
  writeFileSync(scen, JSON.stringify({ player: { invuln_ticks: 1000000 }, wind_enabled: false }));
  const t0 = performance.now();
  const r = spawnSync('node', ['src/headless.js', '--seed', '1', '--night', String(night), '--ticks', '21600', '--scenario', scen, '--out', join(runsDir, `perf-n${night}.jsonl`)], { cwd: ROOT });
  const ms = performance.now() - t0;
  const ok = r.status === 0 && ms <= 30000;
  allPass &&= ok;
  const end = readFileSync(join(runsDir, `perf-n${night}.jsonl`), 'utf8').trim().split('\n').at(-1);
  md.push(`| ${night} | ${(ms / 1000).toFixed(2)} s | ${ok ? 'PASS' : 'FAIL'} · end=\`${end}\` |`);
}

// 3. Unit/CLI tests
const t = spawnSync('npm test', { cwd: ROOT, encoding: 'utf8', shell: true });
const testOut = (t.stdout + t.stderr).replace(/\r/g, '');
writeFileSync(join(outDir, 'test-output.txt'), testOut);
const summary = testOut.split('\n').filter((l) => /^ℹ (tests|pass|fail)/.test(l)).join(' · ');
allPass &&= t.status === 0;
md.push('', '## npm test', '', `Exit code ${t.status}. ${summary} — full log: [test-output.txt](test-output.txt)`);

// 4. Ticket-04 bench / soak results produced by the real commands (if present in this proof folder)
const readJson = (f) => {
  try {
    return JSON.parse(readFileSync(join(outDir, f), 'utf8'));
  } catch {
    return null;
  }
};
const b = readJson('bench.json');
const sk = readJson('soak.json');
if (b || sk) md.push('', '## Benchmark & soak (Ticket-04 thresholds, measured on the dev machine; the grader re-measures)', '', '| Metric | Value | Threshold | Result |', '|---|---|---|---|');
if (b) {
  md.push(`| avg_fps | ${b.avg_fps} | ≥ 60 | ${b.avg_fps >= 60 ? 'PASS' : 'FAIL'} |`, `| p1_low_fps | ${b.p1_low_fps} | ≥ 30 | ${b.p1_low_fps >= 30 ? 'PASS' : 'FAIL'} |`, `| load_ms | ${b.load_ms} | ≤ 10000 | ${b.load_ms <= 10000 ? 'PASS' : 'FAIL'} |`, `| frame_ms_p95 / frames / peak_mem_mb | ${b.frame_ms_p95} / ${b.frames} / ${b.peak_mem_mb} | — | info |`);
  md.push('', `Renderer: ${b.renderer}  `, `OS: ${b.os}`, '');
}
if (sk) md.push(`| soak crashes | ${sk.crashes} | = 0 | ${sk.crashes === 0 ? 'PASS' : 'FAIL'} |`, `| soak mem_end / mem_start | ${sk.mem_end_mb} / ${sk.mem_start_mb} MB = ${(sk.mem_end_mb / sk.mem_start_mb).toFixed(3)} | ≤ 1.2 | ${sk.mem_end_mb <= 1.2 * sk.mem_start_mb ? 'PASS' : 'FAIL'} |`, `| soak results | ${sk.results.join(', ')} | — | info |`);

md.push('', `**Overall: ${allPass ? 'PASS' : 'FAIL'}**`, '');
writeFileSync(join(outDir, 'SUMMARY.md'), md.join('\n'));
console.log(`wrote ${rel(join(outDir, 'SUMMARY.md'))} — overall ${allPass ? 'PASS' : 'FAIL'}`);
process.exit(allPass ? 0 : 1);
